package ma.adria.transactionservice.service;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.transaction.annotation.Transactional;import ma.adria.transactionservice.repository.TransactionRepository;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.slf4j.*;
@Component public class EventPublisher {private static final Logger log=LoggerFactory.getLogger(EventPublisher.class);private final TransactionRepository r;private final KafkaTemplate<String,String> kafka;private final ObjectMapper json;
public EventPublisher(TransactionRepository r,KafkaTemplate<String,String> kafka,ObjectMapper json){this.r=r;this.kafka=kafka;this.json=json;}
@Scheduled(fixedDelay=3000) @Transactional public void publish(){for(var candidate:r.findTop100ByStatusAndPublishedFalseOrderByCreatedAtAsc("COMPLETED")){var t=r.lock(candidate.id).orElseThrow();if(t.published)continue;try{var event=Map.of("eventId",t.id,"eventType","TransactionCreated","transactionId",t.id,"accountId",t.accountId,"amount",t.amount,"currency",t.currency,"occurredAt",t.createdAt);kafka.send("bank.transactions.created",t.accountId.toString(),json.writeValueAsString(event)).get(5,java.util.concurrent.TimeUnit.SECONDS);t.published=true;}catch(Exception ex){log.warn("Publication différée pour {}",t.id);break;}}}
}
